"use client";
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import type {HandoffScope} from '@/lib/cashier-handoff';
type Request={request:string;reason:string};
export function CashierBankMatchReverse({scope,match,reversed,onSaved}:{scope:HandoffScope;match:string;reversed:boolean;onSaved:()=>void}){
 const [pending,setPending]=useState<Request|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');const alive=useRef(false),lock=useRef(false);const key='irp.match.reversal.v1:'+ [scope.tenant,scope.property,scope.actor,match].join(':');
 function read():Request|null{const raw=sessionStorage.getItem(key);if(raw===null)return null;const r=JSON.parse(raw);if(!r||typeof r.request!=='string'||!/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(r.request)||typeof r.reason!=='string'||r.reason!==r.reason.trim()||r.reason.length<4||r.reason.length>500||/[\x00-\x1f\x7f]/.test(r.reason))throw Error('Invalid pending reversal. Preserve it for recovery.');return {request:r.request,reason:r.reason}}
 useEffect(()=>{alive.current=true;try{setPending(read())}catch(e){setError(e instanceof Error?e.message:'Unable to recover reversal.')}return()=>{alive.current=false}},[key]);
 async function identify(){const u=await hotelClient().auth.getUser();if(u.error||u.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen matches.');}
 async function run(r:Request,status=false){if(lock.current)return;lock.current=true;setBusy(true);setError('');setMessage('');try{await identify();if(!alive.current)return;const prior=read();if(prior&&JSON.stringify(prior)!==JSON.stringify(r))throw Error('Recover the pending reversal first.');const encoded=JSON.stringify(r);sessionStorage.setItem(key,encoded);if(sessionStorage.getItem(key)!==encoded)throw Error('Unable to preserve reversal recovery.');read();setPending(r);
 const value=await hotelRpc(status?'cashier_bank_reconciliation_status':'reverse_cashier_bank_match',status?{p_tenant:scope.tenant,p_property:scope.property,p_request:r.request,p_kind:'reversal'}:{p_tenant:scope.tenant,p_property:scope.property,p_match:match,p_request:r.request,p_reason:r.reason,p_confirmed:true});await identify();if(!alive.current)return;
 const v=value as Record<string,unknown>;if(!v||v.schema_version!==1||v.tenant_id!==scope.tenant||v.property_id!==scope.property||v.actor_id!==scope.actor||v.request_id!==r.request)throw Error('Reverse receipt scope changed.');let receipt=v;
 if(status){if(v.kind!=='reversal'||typeof v.found!=='boolean')throw Error('Invalid reversal recovery.');if(!v.found){if(v.result!==null)throw Error('Invalid reversal recovery.');if(!reversed){setMessage('No saved reversal found. Retry the original request.');return}sessionStorage.removeItem(key);if(sessionStorage.getItem(key)!==null)throw Error('Unable to clear pending reversal.');setPending(null);setMessage('Another reversal is already recorded. Your unsaved request was cleared.');return}receipt=v.result as Record<string,unknown>}
 if(!receipt||receipt.schema_version!==1||receipt.tenant_id!==scope.tenant||receipt.property_id!==scope.property||receipt.actor_id!==scope.actor||receipt.request_id!==r.request||receipt.match_id!==match||receipt.reason!==r.reason||receipt.reversed!==true||receipt.bank_transaction_reversed!==false||receipt.journal_posted!==false||typeof receipt.replayed!=='boolean'||typeof receipt.created_at!=='string')throw Error('Reverse receipt does not match the request.');
 sessionStorage.removeItem(key);if(sessionStorage.getItem(key)!==null)throw Error('Unable to clear pending reversal.');setPending(null);setMessage('Match reversed. The original match remains in history.');onSaved();
 }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Reverse interrupted. Check the saved result.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 const [cancelConfirmed,setCancelConfirmed]=useState(false);
 async function cancel(){if(lock.current||!pending||!cancelConfirmed)return;const request=pending.request;lock.current=true;setBusy(true);setError('');setMessage('');try{await identify();if(!alive.current)return;const v=await hotelRpc('cancel_cashier_reconciliation_action',{p_tenant:scope.tenant,p_property:scope.property,p_request:request,p_kind:'reversal',p_confirmed:true}) as Record<string,unknown>;await identify();if(!alive.current)return;if(!v||v.schema_version!==1||v.tenant_id!==scope.tenant||v.property_id!==scope.property||v.actor_id!==scope.actor||v.request_id!==request||v.kind!=='reversal'||v.cancelled!==true||typeof v.replayed!=='boolean'||typeof v.created_at!=='string')throw Error('Cancellation receipt does not match the pending request.');const current=read();if(current&&current.request!==request)throw Error('A different request is pending.');sessionStorage.removeItem(key);if(sessionStorage.getItem(key)!==null)throw Error('Unable to clear cancelled request.');setPending(null);setCancelConfirmed(false);setMessage('Unsaved request cancelled. Delayed retries cannot create it.')}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Cancellation interrupted. Retry to confirm its result.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <section>{pending?<><label><input type="checkbox" checked={cancelConfirmed} disabled={busy} onChange={e=>setCancelConfirmed(e.target.checked)}/>Cancel this unsaved request.</label><button disabled={busy||!cancelConfirmed} onClick={()=>void cancel()}>Cancel pending request</button><p>Pending reversal: {pending.reason}</p><button disabled={busy} onClick={()=>void run(pending)}>Retry match reversal</button><button disabled={busy} onClick={()=>void run(pending,true)}>Check match reversal</button></>:!reversed&&<details><summary>Reverse incorrect match</summary><form onSubmit={e=>{e.preventDefault();const reason=String(new FormData(e.currentTarget).get('reason')).trim();if(reason.length<4||reason.length>500||/[\x00-\x1f\x7f]/.test(reason)){setError('Enter a valid explanation.');return}void run({request:crypto.randomUUID(),reason})}}><fieldset disabled={busy}><label>Reverse explanation<input name="reason" required minLength={4} maxLength={500}/></label><label><input type="checkbox" required/>I confirm this match is incorrect. This does not recover money from a bank.</label><button>Reverse bank match</button></fieldset></form></details>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>
}
